-- Follow-up to 20260909200000. That migration only merged rows with an
-- identical NON-BLANK city. This one also catches the very common case where
-- the duplicate rows agree on a single city but one copy was seeded with the
-- city left blank (e.g. "ACS Medical College and Hospital", Chennai — a third
-- row had city NULL and survived the first pass).
--
-- Scope: groups of active universities sharing lower(name) + lower(state) +
-- stream where the rows that DO carry a city all name the SAME one (exactly
-- one distinct non-blank city across the group). Winner per group = has a
-- city, then most programs, then most reviews, then oldest, then lowest id.
-- Groups where the rows genuinely name two or more different cities
-- ("Government Medical College" across districts) are left untouched.
--
-- 188 loser rows across 170 winners. Same temp-table-free, fully
-- idempotent structure as 20260909200000 (every id column here is Postgres
-- text, not uuid).

-- programs: move exactly one program per (winner, name) to the winner — the
-- winner must not already have that name, AND when several losers feeding the
-- same winner share a program name only the first is moved (DISTINCT ON), so
-- the (university_id, name) unique index can't be violated mid-statement.
