UPDATE "universities" w
SET "city" = l."city", "updated_at" = now()
FROM m
JOIN "universities" l ON l."id" = m."loser_id"
WHERE w."id" = m."winner_id"
  AND (w."city" IS NULL OR btrim(w."city") = '')
  AND l."city" IS NOT NULL AND btrim(l."city") <> '';

